// P8.INCRVACUUM phase17 §5e — UCL pin tests for the two engine fixes
// committed for incrvacuum2 4.1 (a433c318, btree divider) and 4.2.1
// (001af0a8, wal_checkpoint PASSIVE mode).
//
// The committed artifacts in testdata/incrvacuum2conformance/ are the
// orafixture scenarios (JSON) + ORACLE_VERSION marker — matching the
// project pattern (walconformance/backupconformance/...). The .db +
// .db-wal binary files are gitignored and regenerated by
// `go run ./tools/orafixture testdata/incrvacuum2conformance/`.
//
// The tests in this file regenerate the fixtures in a temp dir (so a
// fresh checkout without `orafixture` having been run still passes)
// and then assert the engine's behavior matches the oracle's
// behavior on the same SQL sequence:
//
//   TestNativeBtreeDividerFixtureReference — incrvacuum2 4.1 (a433c318):
//     the committed 4.1 scenario's oracle DB must pass
//     `PRAGMA integrity_check` == "ok" and contain exactly 16384 rows.
//     This locks the scenario's expected output; a regeneration drift
//     or hand-edit of the JSON surfaces immediately. The engine-side
//     boundary pin lives in
//     frigolite_p8_incrvacuum_ucl_test.go::TestNativeBtreeDividerMatchesSQLite.
//
//   TestNativeWalCheckpointPassiveFixtureReference — incrvacuum2 4.2.1
//     (001af0a8): the committed 4.2.1 scenario's oracle DB must pass
//     `PRAGMA integrity_check` == "ok", contain 2 rows in t1, and
//     produce a non-empty -wal file (PASSIVE must keep committed
//     frames in -wal, not truncate to the 32-byte header). The
//     engine-side boundary pin lives in
//     frigolite_p8_incrvacuum_ucl_test.go::TestNativeWalCheckpointHonorsMode.
//
// Both tests skip cleanly when /usr/bin/sqlite3 is absent (CI
// installs one, but a developer without it still gets a green build).

package frigolite

import (
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

// incrvacuum2ScenariosDir is the path to the committed orafixture
// scenarios (testdata/incrvacuum2conformance/, produced by
// tools/orafixture).
const incrvacuum2ScenariosDir = "testdata/incrvacuum2conformance"

// sqliteCLIBin returns the resolved sqlite3 CLI path or the empty
// string when unavailable.
func sqliteCLIBin() string {
	for _, c := range []string{"/usr/bin/sqlite3", "sqlite3"} {
		if p, err := exec.LookPath(c); err == nil {
			return p
		}
	}
	return ""
}

// runSqliteOnDB opens `bin dbpath` and feeds it the SQL commands on
// stdin. Returns the trimmed combined output. The CLI's `-bail` causes
// any statement error to fail the run; errors are test-fatal because
// the expected behavior here is "passes integrity_check + count".
func runSqliteOnDB(t *testing.T, bin, dbpath string, stmts ...string) string {
	t.Helper()
	args := append([]string{dbpath, "-bail", "-noheader", "-separator", "|", "-list"}, stmts...)
	cmd := exec.Command(bin, args...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("sqlite3 %s %v: %v\noutput: %s", dbpath, stmts, err, string(out))
	}
	return strings.TrimSpace(string(out))
}

// regenIncFixture regenerates the named fixture (without .db
// extension) in dir using `go run ./tools/orafixture`. The tool
// writes <name>.db (and -wal if walFiles=true) into dir. Returns the
// resolved .db path. Test-fatal if orafixture is unavailable or
// fails.
//
// We invoke orafixture as a subprocess so the same generator that
// produces the committed fixtures also produces the test's local
// copy — this matches how other conformance suites in the project
// consume testdata/<feature>conformance/ artifacts.
func regenIncFixture(t *testing.T, dir, name string) string {
	t.Helper()
	projectRoot, err := os.Getwd()
	if err != nil {
		t.Fatalf("os.Getwd: %v", err)
	}
	cmd := exec.Command("go", "run", "./tools/orafixture",
		filepath.Join(projectRoot, incrvacuum2ScenariosDir, name+".json"))
	cmd.Dir = projectRoot
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("regen fixture %s: %v\n%s", name, err, string(out))
	}
	// Move the produced artifacts into dir so the test can rely on
	// a self-contained temp dir.
	src := filepath.Join(projectRoot, incrvacuum2ScenariosDir, name+".db")
	srcWal := src + "-wal"
	srcShm := src + "-shm"
	dst := filepath.Join(dir, name+".db")
	if err := os.Rename(src, dst); err != nil {
		t.Fatalf("move %s -> %s: %v", src, dst, err)
	}
	if _, err := os.Stat(srcWal); err == nil {
		if rerr := os.Rename(srcWal, dst+"-wal"); rerr != nil {
			t.Fatalf("move %s -> %s: %v", srcWal, dst+"-wal", rerr)
		}
	}
	if _, err := os.Stat(srcShm); err == nil {
		if rerr := os.Rename(srcShm, dst+"-shm"); rerr != nil {
			t.Fatalf("move %s -> %s: %v", srcShm, dst+"-shm", rerr)
		}
	}
	return dst
}

// TestNativeBtreeDividerFixtureReference locks down the committed 4.1
// oracle scenario (testdata/incrvacuum2conformance/
// incrvacuum2-4-1-btree-divider.json) by regenerating its fixture
// via `go run ./tools/orafixture` and asserting the oracle's output:
//
//  1. PRAGMA integrity_check returns "ok".
//  2. SELECT count(*) FROM t1 returns 16384 (14-step INSERT-SELECT
//     doubling from 1 initial row).
//
// If either assertion fails, the committed scenario has rotted
// (regeneration drift, manual edit, or oracle version bump). The
// engine-side 4.1 boundary pin lives in
// frigolite_p8_incrvacuum_ucl_test.go::TestNativeBtreeDividerMatchesSQLite
// which drives the same SQL into the engine and asserts the
// engine's count + integrity_check (via the engine's own query API)
// matches the oracle.
func TestNativeBtreeDividerFixtureReference(t *testing.T) {
	bin := sqliteCLIBin()
	if bin == "" {
		t.Skip("sqlite3 CLI not available; skipping oracle fixture reference")
	}

	dir := t.TempDir()
	dbPath := regenIncFixture(t, dir, "incrvacuum2-4-1-btree-divider")

	ic := runSqliteOnDB(t, bin, dbPath, "PRAGMA integrity_check;")
	if ic != "ok" {
		t.Fatalf("oracle 4.1 fixture integrity_check = %q, want ok (scenario produces a bad fixture — check testdata/incrvacuum2conformance/incrvacuum2-4-1-btree-divider.json)", ic)
	}
	countStr := runSqliteOnDB(t, bin, dbPath, "SELECT count(*) FROM t1;")
	count, err := strconv.Atoi(countStr)
	if err != nil {
		t.Fatalf("oracle 4.1 fixture count parse %q: %v", countStr, err)
	}
	const wantCount = 16384
	if count != wantCount {
		t.Fatalf("oracle 4.1 fixture count = %d, want %d", count, wantCount)
	}
}

// TestNativeWalCheckpointPassiveFixtureReference locks down the
// committed 4.2.1 oracle scenario (testdata/incrvacuum2conformance/
// incrvacuum2-4-2-1-wal-checkpoint-passive.json) by regenerating its
// fixture and asserting the oracle's output:
//
//  1. The -wal file is non-empty (PASSIVE must keep committed frames
//     in -wal, not truncate to the 32-byte header). Stat BEFORE
//     running sqlite3 on the db — the CLI's default
//     wal_autocheckpoint may auto-checkpoint on open, which would
//     truncate the -wal and mask the PASSIVE invariant.
//  2. PRAGMA integrity_check returns "ok".
//  3. SELECT count(*) FROM t1 returns 2 (the scenario's 2 INSERTs).
//
// If any assertion fails, the committed scenario has rotted. The
// engine-side 4.2.1 boundary pin lives in
// frigolite_p8_incrvacuum_ucl_test.go::TestNativeWalCheckpointHonorsMode
// which asserts engine -wal size is preserved and TRUNCATE resets
// to 32 bytes.
func TestNativeWalCheckpointPassiveFixtureReference(t *testing.T) {
	bin := sqliteCLIBin()
	if bin == "" {
		t.Skip("sqlite3 CLI not available; skipping oracle fixture reference")
	}

	dir := t.TempDir()
	dbPath := regenIncFixture(t, dir, "incrvacuum2-4-2-1-wal-checkpoint-passive")

	// Stat -wal FIRST (before sqlite3 opens the db; the CLI may
	// auto-checkpoint on open and clear the -wal).
	walStat, err := os.Stat(dbPath + "-wal")
	if err != nil {
		t.Fatalf("stat oracle -wal fixture: %v", err)
	}
	if walStat.Size() == 0 {
		t.Fatalf("oracle 4.2.1 -wal fixture is empty; expected committed frames after PASSIVE (PASSIVE must preserve -wal)")
	}

	ic := runSqliteOnDB(t, bin, dbPath, "PRAGMA integrity_check;")
	if ic != "ok" {
		t.Fatalf("oracle 4.2.1 fixture integrity_check = %q, want ok (scenario produces a bad fixture — check testdata/incrvacuum2conformance/incrvacuum2-4-2-1-wal-checkpoint-passive.json)", ic)
	}
	countStr := runSqliteOnDB(t, bin, dbPath, "SELECT count(*) FROM t1;")
	count, err := strconv.Atoi(countStr)
	if err != nil {
		t.Fatalf("oracle 4.2.1 fixture count parse %q: %v", countStr, err)
	}
	const wantCount = 2
	if count != wantCount {
		t.Fatalf("oracle 4.2.1 fixture count = %d, want %d", count, wantCount)
	}
}
